    model.nutrition = pyo.Constraint(model.N, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "foods": ["Food_1", "Food_2", "Food_3", "Food_4", "Food_5", "Food_6", "Food_7"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Food_1": 6,
        "Food_2": 2,
        "Food_3": 10,
        "Food_4": 6,
        "Food_5": 4,
        "Food_6": 1,
        "Food_7": 9,
    },
    "content": {
        # nutrient -> {food -> amount per unit}
        "protein": {
            "Food_1": 6, "Food_2": 16, "Food_3": 12, "Food_4": 9,
            "Food_5": 12, "Food_6": 12, "Food_7": 13,
        },
        "carbs": {
            "Food_1": 3, "Food_2": 3, "Food_3": 17, "Food_4": 28,
            "Food_5": 17, "Food_6": 14, "Food_7": 20,
        },
        "calories": {
            "Food_1": 73, "Food_2": 181, "Food_3": 231, "Food_4": 160,
            "Food_5": 209, "Food_6": 184, "Food_7": 118,
        },
    },
    "requirement": {
        "protein": 59,
        "carbs": 179,
        "calories": 2414,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: number of servings of each food (integer counts)
    model.servings = pyo.Var(
        model.FOODS,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # Objective: minimise total cost
    def cost_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=cost_rule, sense=pyo.minimize)

    # One constraint per nutrient: total intake >= requirement
    def nutrient_rule(m, n):
        return sum(
            d["content"][n][f] * m.servings[f] for f in m.FOODS
        ) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(
        model.NUTRIENTS, rule=nutrient_rule
    )

    return model
